window.ATLAS.addDetails("society.edges",{"edges":{
"auctions:game-theory":{"type":"application","label":{"zh":"占优策略的拍卖实例","en":"Dominant strategy in an auction"},"reason":{"zh":"第二价格拍卖里，无论对手怎么报，说真话都不比别的报价差，是占优策略的一个具体例子。","en":"In a second-price auction, telling the truth is never worse than any other bid whatever the rival does, a concrete dominant strategy."},"source":"../math/applied/auction-basics/#step1"},
"auctions:mechanism-auction":{"type":"foundation","label":{"zh":"拍卖是机制的一个实例","en":"An auction is one instance of a mechanism"},"reason":{"zh":"拍卖页讲出价与成交，机制页追问规则本身：同一群人、同一件物品，换一条成交规则，报价与结果全变。","en":"The auction page covers bids and sales; the mechanism page asks about the rule itself: same people, same item, a different settlement rule, and bids and outcome all change."},"source":"../math/applied/mechanism-design/#s1"},
"compound-interest:fees-compounding":{"type":"foundation","label":{"zh":"费率改的是复利公式里的 r","en":"A fee changes the r in the compound formula"},"reason":{"zh":"复利 A = P(1+r)ᵗ；收 f 的费就变成 P(1+r−f)ᵗ。两条指数曲线的差距不是每年固定一点，而是随 t 越拉越大。","en":"Compounding gives A = P(1+r)ᵗ; a fee f turns it into P(1+r−f)ᵗ. The gap between the two exponential curves is not a fixed amount per year but widens with t."},"source":"../investment/rates/fees-compounding/#step1"},
"compound-interest:interest-rates-bonds":{"type":"foundation","label":{"zh":"折现是复利倒过来","en":"Discounting is compounding in reverse"},"reason":{"zh":"现值 PV = FV/(1+r)ᵗ 把复利公式倒过来；把债券的每笔未来现金逐一折现再加总，就是它今天的价格。","en":"Present value PV = FV/(1+r)ᵗ runs the compound-interest formula backwards; discount each of a bond’s future payments this way, add them up, and you have its price today."},"source":"../investment/rates/interest-rates-bonds/#step1"},
"diversification:risk-pooling":{"type":"connection","label":{"zh":"同样的 1/√N 直觉，机制不同","en":"The same 1/√N intuition, a different mechanism"},"reason":{"zh":"保险靠很多人各自独立出险，平均下来就稳；投资分散靠资产低相关。两者都是“平均能熨平波动”，但共同灾难和系统风险都会让波动停在一个下限。","en":"Insurance relies on many people’s claims being independent, so the average is steady; diversification relies on low correlation between assets. Both are “averaging smooths the wobble”, and in both a common catastrophe or systematic risk leaves a floor."},"source":"../investment/basics/diversification/#step3"},
"ethical-frameworks:veil-of-ignorance":{"type":"connection","label":{"zh":"公平框架的一个思想实验","en":"A thought experiment for the fairness lens"},"reason":{"zh":"无知之幕让选择规则的人不知道自己会落在哪个位置，从而逼着他像关心自己一样关心最差的位置，是检验“代价是否公平分摊”的一个工具。","en":"The veil of ignorance hides from rule-makers which position they will occupy, forcing them to care about the worst position as if it were their own — a tool for testing whether costs are shared fairly."},"source":"../psychology/ethics/veil-of-ignorance/#step0"},
"exp-log:vowel-formants":{"type":"application","label":{"zh":"对数刻度让缩放变成平移","en":"A log scale turns rescaling into shifting"},"reason":{"zh":"元音图两轴用对数刻度，相同距离代表相同倍数；所以按说话人整体乘一个比例来归一化，在图上就是把整圈平移。","en":"Both axes of the vowel plot are logarithmic, so equal distances mean equal ratios; normalising a speaker by multiplying by one factor is then just shifting the whole loop."},"source":"../language/phonology/vowel-space/#step4"},
"expected-value:ethical-frameworks":{"type":"application","label":{"zh":"把后果写成期望值","en":"Writing consequences as an expected value"},"reason":{"zh":"结果主义的计算常写成 E = p·benefit − (1−p)·harm；它能比较后果，却不会自动回答同意、尊严或分配的问题。","en":"Consequentialist reckoning is often written E = p·benefit − (1−p)·harm; it compares outcomes, but does not by itself settle consent, dignity or distribution."},"source":"../psychology/ethics/ethics-decisions/#step1"},
"expected-value:risk-return":{"type":"foundation","label":{"zh":"期望不等于到手","en":"Expected is not received"},"reason":{"zh":"平均回报是所有可能结果按概率加权的期望值，到手的却是某一年真实发生的那一个；所以平均 5% 的投资里照样会冒出亏损的年份。","en":"The average return is the expected value — every possible outcome weighted by its probability — but what you actually get is the one outcome that happens in a given year; so an investment averaging 5% still throws up losing years."},"source":"../investment/basics/risk-return/#step4"},
"expected-value:veil-of-ignorance":{"type":"foundation","label":{"zh":"平均原则就是期望值","en":"The average rule is an expected value"},"reason":{"zh":"海萨尼假设落到每个位置的概率相等，于是比较各社会的平均福祉——正是对位置取期望值；罗尔斯的反驳则是：一生只抽一次，期望值未必是该看的数。","en":"Harsanyi assumes every position is equally likely and so compares average welfare — the expected value over positions; Rawls replies that with only one draw in a lifetime, the expected value is not necessarily the number to look at."},"source":"../psychology/ethics/veil-of-ignorance/#step1"},
"game-theory:externalities":{"type":"connection","label":{"zh":"公地悲剧是多人博弈","en":"The commons is a many-player game"},"reason":{"zh":"每个牧民各自最优的选择合起来使总利润下降，这是纳什均衡劣于合作结果的又一例。","en":"Each herder’s individually best choice adds up to lower total profit, another case of a Nash equilibrium worse than the cooperative outcome."},"source":"../math/applied/externalities/#step4"},
"mechanism-auction:game-theory":{"type":"foundation","label":{"zh":"报价行为要用博弈来读","en":"Bidding behavior reads as a game"},"reason":{"zh":"每个竞标者都按私人价值算计着报，机制设计就是给这场算计定规则——报价不是随手写的数，是博弈里的策略。","en":"Every bidder calculates from private value, so mechanism design is rule-setting for that calculation — a bid is not a number written casually, it is a strategy in a game."},"source":"../math/applied/mechanism-design/#s0"},
"mechanism-auction:prisoners-dilemma":{"type":"connection","label":{"zh":"第二价让说真话不再吃亏","en":"Second-price makes truth-telling cost nothing"},"reason":{"zh":"第一价里人人压价藏真实价值，像囚徒困境里各自算计；第二价收第二高报价，说真话不再吃亏，规则改写了博弈的 payoff。","en":"Under first-price everyone shades their true value, calculating like prisoners in a dilemma; second-price charges the runner-up bid, so truth-telling stops costing anything — the rule rewrites the game's payoff."},"source":"../math/applied/mechanism-design/#s1"},
"montecarlo:auctions":{"type":"application","label":{"zh":"用随机抽样验证收益相等","en":"Simulation checks revenue equivalence"},"reason":{"zh":"多轮随机抽取估值并累计平均，两种规则的平均收益靠近同一个理论值，这是蒙特卡洛估计的直接应用。","en":"Drawing values at random over many rounds and averaging brings both rules to the same theoretical value, a direct use of Monte Carlo estimation."},"source":"../math/applied/auction-basics/#step2"},
"phonemes:vowel-formants":{"type":"connection","label":{"zh":"辅音靠发音特征，元音靠共振峰","en":"Consonants by features, vowels by formants"},"reason":{"zh":"辅音的对立多由发音部位、方式和清浊这些开关决定；元音的区别则落在声道共鸣上，用前两个共振峰 F1、F2 在平面上定位。","en":"Consonant contrasts are mostly set by switches — place, manner and voicing; vowels differ in the vocal tract’s resonances and are located on a plane by the first two formants, F1 and F2."},"source":"../language/phonology/vowel-space/#step0"},
"prisoners-dilemma:game-theory":{"type":"connection","label":{"zh":"占优策略的反例式应用","en":"A dilemma built on dominance"},"reason":{"zh":"第 0 步的收益矩阵里背叛是占优策略，却使双方都不如合作，是博弈论“占优均衡不一定最优”的经典例子。","en":"In step 0’s payoff matrix defection is dominant yet leaves both worse than cooperating, the classic case that a dominant-strategy equilibrium need not be best."},"source":"../math/applied/prisoners-dilemma/#step0"},
"regression-correlation:diversification":{"type":"foundation","label":{"zh":"ρ 从 1 到 −1","en":"ρ from 1 to −1"},"reason":{"zh":"等权两只资产时组合波动是 σ·√((1+ρ)/2)：ρ = 1 不降，ρ = 0 降到约 0.71 倍，ρ = −1 完全抵消——相关系数就是“是否一起动”的那个数。","en":"With two equal-weight assets the portfolio volatility is σ·√((1+ρ)/2): no reduction at ρ = 1, down to about 0.71 times at ρ = 0, fully cancelled at ρ = −1 — the correlation coefficient is the number for “moving together”."},"source":"../investment/basics/diversification/#step1"},
"resonance:vowel-formants":{"type":"foundation","label":{"zh":"声道是一组共鸣腔","en":"The vocal tract is a set of resonators"},"reason":{"zh":"从喉到唇的声道像共鸣腔，把某些频率附近的谐波放大；舌头和嘴唇改变腔的形状，共振频率跟着移动，元音就变了。","en":"The tract from larynx to lips acts like a resonator, amplifying harmonics near certain frequencies; tongue and lips change its shape, the resonant frequencies move, and the vowel changes."},"source":"../language/phonology/vowel-space/#step0"},
"sound-vibration:phonemes":{"type":"foundation","label":{"zh":"浊音就是声带在振动","en":"Voicing is the vocal folds vibrating"},"reason":{"zh":"声音来自振动；清和浊的区别不是音量，而是发音时声带振不振动——摸着喉咙念 /s/ 和 /z/ 就能感觉到。","en":"Sound comes from vibration; voiceless versus voiced is not about loudness but whether the vocal folds vibrate — touch your throat while saying /s/ and /z/ and you can feel it."},"source":"../language/phonology/phonemes/#step0"},
"spectrum:vowel-formants":{"type":"foundation","label":{"zh":"元音的频谱：谐波加包络峰","en":"A vowel’s spectrum: harmonics under envelope peaks"},"reason":{"zh":"浊音的波形每秒重复 F0 次，频谱上是 F0、2F0、3F0…… 一排谐波；共振峰是这些谐波上方包络的峰，要在频谱里才看得见。","en":"A voiced sound repeats F0 times a second, giving a row of harmonics at F0, 2F0, 3F0 … in its spectrum; formants are peaks in the envelope over those harmonics, visible only in the spectrum."},"source":"../language/phonology/vowel-space/#step0"},
"stocks-bonds:interest-rates-bonds":{"type":"foundation","label":{"zh":"债券是一串约定的未来现金","en":"A bond is a promised stream of future cash"},"reason":{"zh":"先知道债券每年付票息、到期还本，才能把它看成一串未来现金流，再按利率折现成今天的价格。","en":"Knowing that a bond pays a coupon every year and returns its principal at maturity is what lets it be seen as a stream of future cash, which interest rates then discount into today’s price."},"source":"../investment/rates/interest-rates-bonds/#step0"},
"stocks-bonds:risk-return":{"type":"connection","label":{"zh":"清偿顺序决定风险","en":"Repayment order sets the risk"},"reason":{"zh":"债主先拿、股东最后拿，所以股票的结果散得更开：好时分红和涨价没有上限，坏时可能归零——风险更大，平均回报也必须更高。","en":"Lenders are paid first and shareholders last, so a stock’s outcomes are spread wider: no cap on dividends and gains in good times, possibly zero in bad — more risk, which must be paid for with a higher average return."},"source":"../investment/basics/stocks-bonds/#step3"},
"supply-demand:externalities":{"type":"application","label":{"zh":"价格漏掉了一部分成本","en":"The price leaves out part of the cost"},"reason":{"zh":"供需均衡只反映买卖双方的私人成本与好处；加上外部损害后社会成本线高于供给线，均衡就偏离社会最优。","en":"Supply–demand equilibrium reflects only the buyers’ and sellers’ private costs and benefits; adding external damage lifts the social cost line above supply and moves equilibrium away from the social optimum."},"source":"../math/applied/externalities/#step1"},
"supply-demand:game-theory":{"type":"connection","label":{"zh":"均衡之外还要看策略互动","en":"Beyond equilibrium, watch strategic interaction"},"reason":{"zh":"供需均衡算的是价格把买卖双方撮合到哪；一旦一方的行动影响另一方的收益（公地、污染），就要用博弈论算每个人在对手行动下的最佳回应——外部性问题正是均衡分析走到博弈论的路口。","en":"Supply-demand equilibrium computes where price matches buyers and sellers; once one side's action affects another's payoff (commons, pollution), game theory computes each player's best response to rivals' moves — externality problems are exactly where equilibrium analysis meets game theory."},"source":"../math/applied/externalities/#step4"},
"supply-demand:stocks-bonds":{"type":"application","label":{"zh":"价格由买卖双方定","en":"Buyers and sellers set the price"},"reason":{"zh":"没人给股票贴价签：想买的人多、想卖的人少，成交价就被抬高，反过来就压低——这就是供求决定价格的机制。","en":"Nobody puts a price tag on a share: more eager buyers than sellers push the trading price up, and the reverse pushes it down — supply and demand at work."},"source":"../investment/basics/stocks-bonds/#step4"},
"variance:diversification":{"type":"foundation","label":{"zh":"组合的方差公式","en":"The portfolio variance formula"},"reason":{"zh":"两只资产组合的波动 σₚ = √(w₁²σ₁² + w₂²σ₂² + 2w₁w₂ρσ₁σ₂)：交叉项里有相关系数 ρ，正是它决定组合能抵消掉多少波动。","en":"A two-asset portfolio’s volatility is σₚ = √(w₁²σ₁² + w₂²σ₂² + 2w₁w₂ρσ₁σ₂): the cross term carries the correlation ρ, which decides how much wobble the mix cancels."},"source":"../investment/basics/diversification/#step1"},
"variance:risk-return":{"type":"foundation","label":{"zh":"用方差量风险","en":"Variance measures risk"},"reason":{"zh":"两种投资平均都是 5%，一个挤在 5% 附近，一个铺到 −10% 到 +20%；方差量的就是结果离平均有多散——散开意味着可能更好，也可能更糟。","en":"Two investments both average 5%, one clustered near 5% and one spread from −10% to +20%; variance measures how scattered the results are around the average — scattered means possibly better, and possibly worse."},"source":"../investment/basics/risk-return/#step1"}
}});
